// Private LIE path: caller-owned storage, no global growth or allocation.
int lie_q2_ids(const int32_t* ids, int32_t* src, int32_t* dst, int32_t* bounds,
               int32_t* scratch, size_t scratch_elems, int experts, int tokens,
               int used, hipStream_t stream) {
    if (!ids || !src || !dst || !bounds || !scratch || experts <= 0 ||
        experts > 512 || tokens <= 0 || used <= 0 || used > 32 ||
        int64_t(tokens) * used > 2048 * 32) return -1;
    const int rows = tokens * used;
    const int blocks = (rows + kIdsRowsPerBlock - 1) / kIdsRowsPerBlock;
    if (scratch_elems < size_t(rows) + size_t(blocks) * (experts + 1)) return -1;
    auto* counts = scratch + rows;
    const size_t lds = size_t(experts + 1) * kIdsWaves * sizeof(int32_t);
    mm_ids_rank_kernel<<<blocks, kIdsRowsPerBlock, lds, stream>>>(
        ids, scratch, counts, rows, experts, used, used);
    if (hipGetLastError() != hipSuccess) return -2;
    mm_ids_bounds_kernel<<<1, 1024, size_t(experts + 1) * sizeof(int32_t), stream>>>(
        counts, bounds, blocks, experts);
    if (hipGetLastError() != hipSuccess) return -2;
    mm_ids_scatter_kernel<<<blocks, kIdsRowsPerBlock, 0, stream>>>(
        ids, scratch, counts, bounds, src, dst, rows, experts, used, 1, used, 1);
    return hipGetLastError() == hipSuccess ? 0 : -2;
}

